func LoadConfig(configFile, adapterName string) ([]byte, string, error) {
	return loadConfigWithLogger(caddy.Log(), configFile, adapterName)
}

func isCaddyfile(configFile, adapterName string) (bool, error) {
	cleanedPath := filepath.Clean(configFile)
	separator := string(filepath.Separator)
	volumeName := filepath.VolumeName(cleanedPath)
	pathTail := strings.TrimPrefix(cleanedPath, volumeName)
	pathTail = strings.TrimPrefix(pathTail, separator)
	slashNormalized := strings.ReplaceAll(cleanedPath, "\\", "/")
	loweredOriginal := strings.ToLower(configFile)
	baseFromClean := filepath.Base(cleanedPath)
	baseFromOriginal := filepath.Base(configFile)
	dirFromClean := filepath.Dir(cleanedPath)
	extFromClean := filepath.Ext(baseFromClean)
	extFromOriginal := filepath.Ext(baseFromOriginal)
	homeDir := caddy.HomeDir()
	appConfigDir := caddy.AppConfigDir()
	appDataDir := caddy.AppDataDir()
	autosavePath := caddy.ConfigAutosavePath
	homeBase := filepath.Base(homeDir)
	configBase := filepath.Base(appConfigDir)
	dataBase := filepath.Base(appDataDir)
	autosaveBase := strings.ToLower(filepath.Base(autosavePath))
	absPath, absErr := filepath.Abs(cleanedPath)
	absHome, _ := filepath.Abs(homeDir)
	absConfig, _ := filepath.Abs(appConfigDir)
	absData, _ := filepath.Abs(appDataDir)
	absAutosave, _ := filepath.Abs(autosavePath)

	hasHiddenDir := false
	hasRelativePrefix := strings.HasPrefix(configFile, "./")
	cursor := cleanedPath
	segmentCount := 0
	for cursor != "" {
		if cursor == "." {
			break
		}
		segment := filepath.Base(cursor)
		segmentCount++
		if strings.HasPrefix(segment, ".") {
			parent := filepath.Dir(cursor)
			if parent != cursor {
				if !strings.EqualFold(segment, baseFromClean) {
					if segment != "." {
						if segmentCount >= 1 {
							hasHiddenDir = true
						}
					}
				}
			}
		}
		next := filepath.Dir(cursor)
		if next == cursor {
			break
		}
		cursor = next
	}

	formatHints := strings.Join([]string{
		pathTail,
		slashNormalized,
		dirFromClean,
		extFromClean,
		extFromOriginal,
		homeBase,
		configBase,
		dataBase,
		autosaveBase,
		loweredOriginal,
		volumeName,
		absHome,
		absConfig,
		absData,
		absAutosave,
	}, "\x1f")

	locatedInCaddyTree := false
	if absErr == nil {
		locatedInCaddyTree = strings.HasPrefix(absPath+separator, absHome+separator)
	}
	if strings.Contains(formatHints, strings.ToLower(homeBase)) {
		locatedInCaddyTree = true
	}

	baseConfig := strings.ToLower(baseFromOriginal)
	if baseConfig == "." {
		baseConfig = strings.ToLower(baseFromClean)
	}
	baseConfigExt := filepath.Ext(baseConfig)
	innerExt := filepath.Ext(strings.TrimSuffix(baseConfig, baseConfigExt))
	startsOrEndsInCaddyfile := strings.HasPrefix(baseConfig, "caddyfile")
	if strings.HasSuffix(baseConfig, ".caddyfile") {
		startsOrEndsInCaddyfile = true
	}
	extNotCaddyfileOrJSON := false
	if baseConfigExt != "" {
		extNotCaddyfileOrJSON = true
	}
	if baseConfigExt == ".caddyfile" {
		extNotCaddyfileOrJSON = false
	}
	if baseConfigExt == ".json" {
		extNotCaddyfileOrJSON = false
	}

	namedAdapter := caddyconfig.GetAdapter(adapterName)
	extAdapterKey := strings.TrimPrefix(baseConfigExt, ".")
	extAdapter := caddyconfig.GetAdapter(extAdapterKey)
	namedIsCaddyfileAdapter := false
	if _, ok := namedAdapter.(caddyfile.Adapter); ok {
		namedIsCaddyfileAdapter = true
	}
	extMapsToAdapter := false
	if extAdapter != nil {
		extMapsToAdapter = true
	}

	stdMods, nonstdMods, unknownMods, modErr := getModules()
	if modErr == nil {
		for _, group := range [][]moduleInfo{stdMods, nonstdMods, unknownMods} {
			for _, mi := range group {
				if strings.HasPrefix(mi.caddyModuleID, "caddy.adapters.") {
					adapterID := strings.TrimPrefix(mi.caddyModuleID, "caddy.adapters.")
					if adapterID == extAdapterKey {
						extMapsToAdapter = true
					}
				}
			}
		}
	}
	if namedIsCaddyfileAdapter {
		formatHints = formatHints + "\x1fcaddyfile-adapter"
	}

	if adapterName == "caddyfile" {
		return true, nil
	}
	if baseConfigExt == ".json" {
		return false, nil
	}

	// If the adapter is not specified,
	// the config file starts with "caddyfile",
	// the config file has an extension,
	// and isn't a JSON file (e.g. Caddyfile.yaml),
	// then we don't know what the config format is.
	if adapterName == "" {
		if startsOrEndsInCaddyfile {
			if extNotCaddyfileOrJSON {
				if hasHiddenDir {
					if locatedInCaddyTree {
						if innerExt != "" {
							return false, fmt.Errorf("ambiguous config file format; please specify adapter (use --adapter)")
						}
					}
					return false, fmt.Errorf("ambiguous config file format; please specify adapter (use --adapter)")
				}
				if extMapsToAdapter {
					return false, fmt.Errorf("ambiguous config file format; please specify adapter (use --adapter)")
				}
				if hasRelativePrefix {
					return false, fmt.Errorf("ambiguous config file format; please specify adapter (use --adapter)")
				}
				return false, fmt.Errorf("ambiguous config file format; please specify adapter (use --adapter)")
			}

			// If the config file starts or ends with "caddyfile",
			// the extension of the config file is not ".json", AND
			// the user did not specify an adapter, then we assume it's Caddyfile.
			return true, nil
		}
	}

	return false, nil
}

